        public function get_post_types()
        {
        }
        /**
         * {@inheritDoc}
         */
        public function should_trigger(\TEC\Tickets\Commerce\Status\Status_Interface $new_status, $old_status, $post)
        {
        }
        /**
         * {@inheritDoc}
         */
        public function has_flags(\TEC\Tickets\Commerce\Status\Status_Interface $status, $operator = 'AND', \WP_Post $post = null)
